using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Object=UnityEngine.Object;
public static class ReduceSceneTrees {
 struct Tree {public Vector3 p;public float scale,yaw;public int type;public bool distant;}
 static Vector3[] backdropVertices;static int[] backdropTriangles;static LODGroup[] sources;static Dictionary<Mesh,Vector3[]> vertexCache=new Dictionary<Mesh,Vector3[]>();
 static long Triangles(Renderer[] rs)=>rs.OfType<MeshRenderer>().Sum(r=>(long)r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3);
 static bool BackdropHeight(Vector3 p,out float height){height=0;for(int k=0;k<backdropTriangles.Length;k+=3){var a=backdropVertices[backdropTriangles[k]];var b=backdropVertices[backdropTriangles[k+1]];var c=backdropVertices[backdropTriangles[k+2]];float d=(b.z-c.z)*(a.x-c.x)+(c.x-b.x)*(a.z-c.z);if(Mathf.Abs(d)<.00001f)continue;float u=((b.z-c.z)*(p.x-c.x)+(c.x-b.x)*(p.z-c.z))/d;float v=((c.z-a.z)*(p.x-c.x)+(a.x-c.x)*(p.z-c.z))/d;float w=1-u-v;if(u<-.0001f||v<-.0001f||w<-.0001f)continue;height=u*a.y+v*b.y+w*c.y;return true;}return false;}
 static Matrix4x4 Matrix(Tree t,Vector3 center,Renderer r)=>Matrix4x4.Translate(-center)*Matrix4x4.TRS(t.p,Quaternion.Euler(0,t.yaw,0),Vector3.one*t.scale)*sources[t.type].transform.worldToLocalMatrix*r.transform.localToWorldMatrix;
 static Bounds PredictBounds(Tree[] trees,Vector3 center){bool first=true;var bounds=new Bounds();foreach(var t in trees)foreach(var r in sources[t.type].GetLODs()[0].renderers.OfType<MeshRenderer>()){var mesh=r.GetComponent<MeshFilter>().sharedMesh;if(!vertexCache.TryGetValue(mesh,out var vertices)){vertices=mesh.vertices;vertexCache.Add(mesh,vertices);}var matrix=Matrix(t,center,r);foreach(var v in vertices){var p=matrix.MultiplyPoint3x4(v);if(first){bounds=new Bounds(p,Vector3.zero);first=false;}else bounds.Encapsulate(p);}}return bounds;}
 static Mesh Build(Tree[] trees,Vector3 center,bool billboard,out Material[] materials){var groups=new Dictionary<Material,List<CombineInstance>>();foreach(var t in trees){var levels=sources[t.type].GetLODs();int index=billboard?levels.Length-1:levels.Length-2;foreach(var r in levels[index].renderers.OfType<MeshRenderer>()){var mesh=r.GetComponent<MeshFilter>().sharedMesh;for(int s=0;s<mesh.subMeshCount;s++){var m=r.sharedMaterials[s];if(!groups.ContainsKey(m))groups.Add(m,new List<CombineInstance>());groups[m].Add(new CombineInstance{mesh=mesh,subMeshIndex=s,transform=Matrix(t,center,r)});}}}var parts=new List<Mesh>();foreach(var group in groups){var m=new Mesh{indexFormat=IndexFormat.UInt32};m.CombineMeshes(group.Value.ToArray(),true,true);parts.Add(m);}var result=new Mesh{indexFormat=IndexFormat.UInt32};result.CombineMeshes(parts.Select(m=>new CombineInstance{mesh=m,transform=Matrix4x4.identity}).ToArray(),false,false);result.RecalculateBounds();foreach(var m in parts)Object.DestroyImmediate(m);materials=groups.Keys.ToArray();return result;}
 static void Replace(MeshFilter filter,Mesh replacement,Material[] mats,string name){var original=filter.sharedMesh;EditorUtility.CopySerialized(replacement,original);original.name=Path.GetFileNameWithoutExtension(AssetDatabase.GetAssetPath(original));EditorUtility.SetDirty(original);filter.sharedMesh=null;filter.sharedMesh=original;filter.GetComponent<MeshRenderer>().sharedMaterials=mats;}
 static void Prune(Transform t){foreach(var c in t.Cast<Transform>().ToArray()){Prune(c);if(c.childCount==0&&c.GetComponents<Component>().Length==1)Object.DestroyImmediate(c.gameObject);}}
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");if(File.Exists("output/TreeOptimization/completed.txt"))throw new Exception("Optimization already applied");var root=GameObject.Find("New_Map").transform;var hills=root.Find("12_Farmyards_and_boundaries/Low poly hill groves");var terrain=root.GetComponentInChildren<Terrain>();var individual=root.GetComponentsInChildren<LODGroup>().Where(l=>l.name.Contains("Tree")&&l.GetLODs().Length>=4).ToArray();sources=root.Find("05_Landscape").GetComponentsInChildren<LODGroup>().Where(l=>l.name.StartsWith("TFP_Beech_Tree_")).GroupBy(l=>l.name).Select(g=>g.First()).Take(3).ToArray();if(sources.Length!=3)throw new Exception("Original sources missing");
  var backdrop=root.Find("12_Farmyards_and_boundaries/Distant rolling hills - backdrop");var bm=backdrop.GetComponent<MeshFilter>().sharedMesh;backdropVertices=bm.vertices.Select(v=>backdrop.TransformPoint(v)).ToArray();backdropTriangles=bm.triangles;var rng=new System.Random(2601026);Func<float,float,float> random=(a,b)=>Mathf.Lerp(a,b,(float)rng.NextDouble());var trees=new List<Tree>();
  for(float z=-66;z<310;z+=8.5f)for(float x=-188;x<188;x+=8.5f){var p=new Vector3(x+random(-3,3),0,z+random(-3,3));float edge=Mathf.Min(Mathf.Min(p.x+192,192-p.x),Mathf.Min(p.z+70,314-p.z));if(edge<3||edge>26)continue;float density=Mathf.PerlinNoise(p.x*.026f+70,p.z*.026f+29);if(rng.NextDouble()>.36f+density*.52f)continue;p.y=terrain.SampleHeight(p)+terrain.transform.position.y-.12f;trees.Add(new Tree{p=p,scale=random(.7f,1.25f),yaw=random(0,360),type=rng.Next(sources.Length)});}
  for(float z=-178;z<422;z+=13)for(float x=-300;x<300;x+=13){var p=new Vector3(x+random(-4.5f,4.5f),0,z+random(-4.5f,4.5f));if(p.x>-191&&p.x<191&&p.z>-69&&p.z<313)continue;float height;if(!BackdropHeight(p,out height))continue;if(rng.NextDouble()>.3f+Mathf.PerlinNoise(p.x*.019f+14,p.z*.019f+61)*.48f)continue;p.y=height-.12f;trees.Add(new Tree{p=p,scale=random(.85f,1.5f),yaw=random(0,360),type=rng.Next(sources.Length),distant=true});}
  var cells=trees.GroupBy(t=>(t.distant?"Outer ":"Slope ")+Mathf.FloorToInt(t.p.x/42)+"_"+Mathf.FloorToInt(t.p.z/42)).ToArray();if(cells.Length!=hills.childCount)throw new Exception("Placement replay mismatch");float maxError=0;long hillsBefore=0,individualBefore=individual.Sum(l=>Triangles(l.GetLODs()[0].renderers));
  // Verify the exact previous grove geometry before replacing any saved mesh data.
  foreach(var cell in cells){var current=hills.Find(cell.Key);if(!current)throw new Exception("Missing cell "+cell.Key);var ts=cell.ToArray();var center=new Vector3(ts.Average(t=>t.p.x),ts.Average(t=>t.p.y),ts.Average(t=>t.p.z));var original=current.GetComponent<LODGroup>().GetLODs()[0].renderers;long expected=ts.Sum(t=>Triangles(sources[t.type].GetLODs()[0].renderers));long actual=Triangles(original);if(expected!=actual)throw new Exception("Source triangle mismatch "+cell.Key+": "+expected+" / "+actual);hillsBefore+=actual;var mesh=((MeshRenderer)original[0]).GetComponent<MeshFilter>().sharedMesh;var predicted=PredictBounds(ts,center);float error=Mathf.Max((predicted.center-mesh.bounds.center).magnitude,(predicted.size-mesh.bounds.size).magnitude);maxError=Mathf.Max(maxError,error);if(error>.03f)throw new Exception("Placement bounds mismatch "+cell.Key+" "+error);}
  Directory.CreateDirectory("Temp/TreeOptimization");EditorSceneManager.SaveScene(root.gameObject.scene,"Temp/TreeOptimization/Gameplay.before-tree-reduction.unity",true);var sample=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/NewMap/FiveHangars/HillTrees/Hill grove 267.asset");long sampleBefore=sample.triangles.Length/3;long hillsAfter=0,hillsFar=0;int removed=0;
  AssetDatabase.StartAssetEditing();try{
   foreach(var cell in cells){var current=hills.Find(cell.Key);var lod=current.GetComponent<LODGroup>();var levels=lod.GetLODs();var ts=cell.ToArray();var center=new Vector3(ts.Average(t=>t.p.x),ts.Average(t=>t.p.y),ts.Average(t=>t.p.z));Material[] billboardMats;var billboard=Build(ts,center,true,out billboardMats);Material[] lowMats=null;Mesh low=null;if(!ts[0].distant)low=Build(ts,center,false,out lowMats);
    // Rewrite all three existing assets, preserving GUIDs and the user's mesh references.
    for(int i=0;i<levels.Length;i++){var r=(MeshRenderer)levels[i].renderers[0];bool useLow=i==0&&!ts[0].distant;Replace(r.GetComponent<MeshFilter>(),useLow?low:billboard,useLow?lowMats:billboardMats,cell.Key+(useLow?" coarse trees":" billboard trees"));r.shadowCastingMode=useLow?ShadowCastingMode.On:ShadowCastingMode.Off;}
    var top=(MeshRenderer)levels[0].renderers[0];var far=(MeshRenderer)levels[2].renderers[0];hillsFar+=Triangles(new Renderer[]{far});if(ts[0].distant){hillsAfter+=Triangles(new Renderer[]{far});lod.SetLODs(new[]{new LOD(.004f,new Renderer[]{far})});Object.DestroyImmediate(top.gameObject);Object.DestroyImmediate(levels[1].renderers[0].gameObject);removed+=2;}else{hillsAfter+=Triangles(new Renderer[]{top});lod.SetLODs(new[]{new LOD(.24f,new Renderer[]{top}),new LOD(.004f,new Renderer[]{far})});Object.DestroyImmediate(levels[1].renderers[0].gameObject);removed++;}lod.RecalculateBounds();Object.DestroyImmediate(billboard);if(low)Object.DestroyImmediate(low);
   }
   foreach(var lod in individual){var levels=lod.GetLODs();var near=levels[levels.Length-2].renderers;var far=levels[levels.Length-1].renderers;var keep=new HashSet<Renderer>(near.Concat(far));var outer=PrefabUtility.GetOutermostPrefabInstanceRoot(lod.gameObject);if(outer)PrefabUtility.UnpackPrefabInstance(outer,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);float size=lod.size;var reference=lod.localReferencePoint;lod.SetLODs(new[]{new LOD(.16f,near),new LOD(.008f,far)});foreach(var r in far)r.shadowCastingMode=ShadowCastingMode.Off;foreach(var r in levels.SelectMany(l=>l.renderers).Distinct().Where(r=>!keep.Contains(r)).ToArray()){var f=r.GetComponent<MeshFilter>();if(f)Object.DestroyImmediate(f);Object.DestroyImmediate(r);removed++;}Prune(lod.transform);lod.size=size;lod.localReferencePoint=reference;}
  }finally{AssetDatabase.StopAssetEditing();}
  AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);long individualAfter=individual.Sum(l=>Triangles(l.GetLODs()[0].renderers));long individualFar=individual.Sum(l=>Triangles(l.GetLODs().Last().renderers));string result="Tree mesh reduction\nExact placement replay: "+trees.Count+" trees in "+cells.Length+" cells; max pre-change local bounds error="+maxError.ToString("F5")+"m.\nHill groves top-detail triangles: "+hillsBefore+" -> "+hillsAfter+"; far representation="+hillsFar+".\nIndividual active map trees: "+individual.Length+"; top-detail triangles: "+individualBefore+" -> "+individualAfter+"; far representation="+individualFar+".\nCombined top-detail triangle reduction="+(100f*(1-(hillsAfter+individualAfter)/(float)(hillsBefore+individualBefore))).ToString("F2")+"%.\nHill grove 267.asset: "+sampleBefore+" -> "+(sample.triangles.Length/3)+" triangles (same GUID).\nUnused high-detail renderer/LOD nodes removed="+removed+".\nNative penultimate LODs (~500 triangles/tree) used nearby; original 8-triangle atlas billboards used far away. Outer hills always use billboards. Tree positions, materials and individual-tree colliders retained. Imported models untouched. No FPS/GPU benchmark claim.";Directory.CreateDirectory("output/TreeOptimization");File.WriteAllText("output/TreeOptimization/completed.txt",result);return result;
 }
}

